-- Which user-source-destination windows contain failures before a success?
SELECT dataset_day,quarter_hour,user_name,src,destination,COUNT(*) FILTER (WHERE failure) failures,COUNT(*) FILTER (WHERE success) successes,MIN(epoch_time) FILTER (WHERE failure) first_failure_s,MAX(epoch_time) FILTER (WHERE success) last_success_s FROM auth_enriched GROUP BY 1,2,3,4,5 HAVING failures>=3 AND successes>=1 AND first_failure_s<last_success_s ORDER BY failures DESC LIMIT 30;
